namespace Lastlight.Core;
public sealed partial class World
{
 public static readonly string[] TreatyKinds=["Safe passage","Resource exchange","Scholarly access","Mutual defense","Sanctuary","Artifact restitution","Tribute"];
 public int TradePrice(string item,bool buying)=>item switch {"medicine"=>buying?2:1,"f-parts"=>buying?3:1,"wood"=>buying?2:1,_=>1};
 private bool AtCounter(Expedition party,long faction,long actor)
 {var site=Region.Sites.First(s=>s.Id==party.SiteId);return site.Kind=="Town"&&site.FactionId==faction&&party.Members.Contains(actor)&&CanAct(actor)&&Find(site.MarketId) is {} marker&&Find(actor) is {} pawn&&pawn.Z==marker.Z&&Distance(pawn,marker)<=2;}
 private CommandResult ApplyRegionCommand(WorldCommand c,Definitions d)
 {
  if(c.Text=="enable"){EnableRegion(d);return new(true,"Living region generated without replacing the settlement.");}if(!Region.Enabled)return new(false,"Enable the living region first.");
  if(c.Text=="depart"){if(Width<116||Height<116)return new(false,"Tactical regional sites require the standard 128-tile settlement map.");return BeginExpedition(c,d);}if(c.Text=="take")return TakeRegionalArtifact(c,d);
  if(c.Text=="quest")
  {var q=Region.Quests.FirstOrDefault(q=>q.Id==c.TargetId);if(q==null||q.Status!="Offered")return new(false,"This contract is unavailable.");if(c.Quantity==0){q.Status="Declined";return new(true,"Contract declined.");}q.Status="Accepted";q.Deadline=Tick+TicksPerDay*12;Chronicle("Quest","Accepted: "+q.Name+".",q.FactionId,q.SiteId,q.ArtifactId);return new(true,"Contract accepted; owner permission and a twelve-day deadline recorded.");}
  if(c.Text=="visitor-buy")return BeginVisitorTrade(c,d);
  var party=Region.Parties.FirstOrDefault(p=>p.Id==c.TargetId);if(party==null)return new(false,"Select an expedition.");
  if(c.Text=="return" && party.State=="Stranded"){if(!party.Members.Any(id=>Body(id) is {Dead:false,Downed:false}))return new(false,"No capable traveler remains; this expedition is stranded.");int at=party.RouteIndex>0?party.Route[party.RouteIndex-1]:Region.Sites.First(s=>s.Id==Region.HomeSiteId).Y*12+6;party.Route=RegionalRoute(Region.HomeSiteId,at)??[];party.RouteIndex=0;party.Returning=true;party.State="Returning";party.NextAt=Tick;return new(true,"Recovered travelers are returning from the stranded route.");}
  if(c.Text=="pack"){if(party.State!="AtSite"||!party.Members.Contains(c.EntityId)||!CanAct(c.EntityId)||c.Quantity is <1 or >40)return new(false,"Select a capable member at the site.");var pawn=Find(c.EntityId)!;var item=Entities.Where(e=>e.DefinitionId==c.DefinitionId&&d.Entities[e.DefinitionId].Kind==EntityKind.ItemStack&&!e.Forbidden&&!Autonomy.Claims.ContainsKey("item:"+e.Id)&&!Region.Artifacts.Any(a=>a.LocalEntityId==e.Id)&&e.Z==pawn.Z&&Distance(e,pawn)<=1&&e.Quantity>=c.Quantity).OrderBy(e=>e.Id).FirstOrDefault();if(item==null||party.Cargo.Values.Sum()+party.Artifacts.Count+c.Quantity>party.Members.Count*40)return new(false,"No unclaimed adjacent goods or insufficient capacity.");item.Quantity-=c.Quantity;if(item.Quantity==0)Apply(new(CommandKind.Remove,item.Id),d);party.Cargo[c.DefinitionId]=party.Cargo.GetValueOrDefault(c.DefinitionId)+c.Quantity;return new(true,"Adjacent ground goods loaded into real expedition cargo.");}
  if(c.Text=="unpack"){if(party.State!="AtSite"||!party.Members.Contains(c.EntityId)||!CanAct(c.EntityId)||c.Quantity is <1 or >40||party.Cargo.GetValueOrDefault(c.DefinitionId)<c.Quantity)return new(false,"Select a capable member at the site and available packed goods.");party.Cargo[c.DefinitionId]-=c.Quantity;var pawn=Find(c.EntityId)!;Drop(c.DefinitionId,c.Quantity,Index(pawn.X,pawn.Y,pawn.Z),d);return new(true,"Packed goods placed physically at the site for eating, medicine or work.");}
  if(c.Text=="return"||c.Text=="travel")
  {if(party.State!="AtSite" || !party.Members.Any(id=>CanAct(id)))return new(false,"Only a capable party at a site can choose a new route.");long target=c.Text=="return"?Region.HomeSiteId:c.Quantity;var current=Region.Sites.First(s=>s.Id==party.SiteId);var destination=Region.Sites.FirstOrDefault(s=>s.Id==target);if(destination==null)return new(false,"Select a destination.");if(destination.Kind=="Town"&&!TradeAccess(destination.FactionId)&&!HasTreaty(destination.FactionId,"Safe passage"))return new(false,"Grievances block entry; resolve the faction's artifact claim or choose a different destination.");var route=RegionalRoute(target,current.Y*Region.Width+current.X);if(route==null)return new(false,"No route.");party.DestinationId=target;party.Route=route;party.RouteIndex=0;party.NextAt=Tick;party.Returning=target==Region.HomeSiteId;party.State=party.Returning?"Returning":"Outbound";foreach(long id in party.Members){Interrupt(id,d);Region.Absent.Add(id);}Chronicle("Expedition","The party chose a route to "+destination.Name+".",destination.FactionId,target,actor:party.Members[0]);return new(true,"Party is traveling with its existing cargo.");}
  var actor=Find(c.EntityId);var site=Region.Sites.FirstOrDefault(s=>s.Id==party.SiteId);if(party.State!="AtSite"||site==null||actor==null||!AtCounter(party,site.FactionId,actor.Id))return new(false,"Move a capable expedition member beside the town trade counter.");var faction=Region.Factions.First(f=>f.Id==site.FactionId);
  if(c.Text is "buy" or "sell")
  {if(!TradeAccess(faction.Id))return new(false,"Trade access is suspended by grievances.");if(c.DefinitionId=="brass"||!d.Entities.TryGetValue(c.DefinitionId,out var definition)||definition.Kind!=EntityKind.ItemStack||c.Quantity is <1 or >40)return new(false,"Select a tradable quantity of goods.");bool buying=c.Text=="buy";int price=TradePrice(c.DefinitionId,buying)*c.Quantity;var seller=buying?faction.Reserves:party.Cargo;var buyer=buying?party.Cargo:faction.Reserves;if(seller.GetValueOrDefault(c.DefinitionId)<c.Quantity||buyer.GetValueOrDefault("brass")<price)return new(false,"Seller stock or buyer brass is insufficient.");if(buyer.GetValueOrDefault(c.DefinitionId)+c.Quantity>10000 || seller.GetValueOrDefault("brass")+price>10000)return new(false,"This inventory cannot hold the proposed stock.");int after=party.Cargo.Values.Sum()+party.Artifacts.Count+(buying?c.Quantity-price:price-c.Quantity);if(after>party.Members.Count*40)return new(false,"Trade exceeds expedition carrying capacity.");seller[c.DefinitionId]-=c.Quantity;buyer[c.DefinitionId]=buyer.GetValueOrDefault(c.DefinitionId)+c.Quantity;buyer["brass"]-=price;seller["brass"]=seller.GetValueOrDefault("brass")+price;Region.TradeTransactions++;faction.Trust=Math.Min(100,faction.Trust+1);Chronicle("Trade","Exchanged "+c.Quantity+" "+definition.Name+" for "+price+" brass with "+faction.Name+".",faction.Id,site.Id,actor:actor.Id);return new(true,"Trade completed against actual cargo and reserves.");}
  if(c.Text=="treaty")
  {string kind=c.DefinitionId;if(!TreatyKinds.Contains(kind)||HasTreaty(faction.Id,kind))return new(false,"Choose a new available agreement.");int threshold=kind=="Mutual defense"?20:kind is "Scholarly access" or "Sanctuary"?10:0;if(faction.Goodwill<threshold||kind=="Scholarly access"&&faction.Trust<10||kind=="Mutual defense"&&faction.Compatibility< -10)return new(false,"Goodwill or trust is insufficient for these terms.");int payment=kind=="Tribute"?3:0;if(party.Cargo.GetValueOrDefault("brass")<payment)return new(false,"Bring the promised tribute.");if(payment>0){party.Cargo["brass"]-=payment;faction.Reserves["brass"]+=payment;}Region.Treaties.Add(new(){Id=Region.NextId++,FactionId=faction.Id,Kind=kind,SignedAt=Tick,Payment=payment,DueAt=payment>0||kind=="Sanctuary"?Tick+TicksPerDay*7:Tick});faction.Trust=Math.Min(100,faction.Trust+2);Chronicle("Treaty","Signed "+kind+" with "+faction.Name+(payment>0?"; three brass is due every seven days.":"."),faction.Id,site.Id,actor:actor.Id);return new(true,"Signed terms persisted; route, access and obligations use this agreement.");}
  if(c.Text=="pay")
  {var treaty=Region.Treaties.FirstOrDefault(t=>t.FactionId==faction.Id&&t.Kind=="Tribute"&&t.Active);if(treaty==null||party.Cargo.GetValueOrDefault("brass")<3)return new(false,"No active tribute or insufficient brass.");party.Cargo["brass"]-=3;faction.Reserves["brass"]+=3;treaty.DueAt=Tick+TicksPerDay*7;Chronicle("Diplomacy","Paid the agreed tribute from expedition cargo.",faction.Id,site.Id,actor:actor.Id);return new(true,"Tribute obligation extended.");}
  if(c.Text=="complete")
  {var quest=Region.Quests.FirstOrDefault(q=>q.Id==c.Quantity&&q.Status=="Accepted"&&q.FactionId==faction.Id);if(quest==null||Tick>quest.Deadline)return new(false,"Select an accepted, unexpired contract for this faction.");if(quest.Reward.Any(k=>faction.Reserves.GetValueOrDefault(k.Key)<k.Value))return new(false,"The faction cannot currently fund the reward.");if(quest.Kind=="Recovery"&&!party.Artifacts.Contains(quest.ArtifactId))return new(false,"Bring the claimed artifact in this party's custody.");if(quest.Kind=="Aid"&&party.Cargo.GetValueOrDefault("meal")<6)return new(false,"Bring six meals for the relief contract.");if(quest.Kind=="Survey"&&!Region.Sites.First(s=>s.Id==quest.SiteId).Instantiated)return new(false,"Visit and survey the named site first.");int cargo=party.Cargo.Values.Sum()+party.Artifacts.Count+quest.Reward.Values.Sum()-(quest.Kind=="Aid"?6:0);if(cargo>party.Members.Count*40)return new(false,"Reward exceeds carrying capacity.");
   if(quest.Kind=="Recovery"){var artifact=Region.Artifacts.First(a=>a.Id==quest.ArtifactId);party.Artifacts.Remove(artifact.Id);artifact.Custody="Faction";artifact.PartyId=0;artifact.SiteId=site.Id;artifact.OwnerFactionId=faction.Id;Region.ArtifactTransfers++;faction.Claims.Remove("artifact:"+artifact.Id);Chronicle("ArtifactTransfer","Transferred "+artifact.Name+" to its claimant through restitution.",faction.Id,site.Id,artifact.Id,actor.Id);}if(quest.Kind=="Aid"){party.Cargo["meal"]-=6;faction.Reserves["meal"]+=6;}foreach(var reward in quest.Reward){faction.Reserves[reward.Key]-=reward.Value;party.Cargo[reward.Key]=party.Cargo.GetValueOrDefault(reward.Key)+reward.Value;}quest.Status="Completed";Remember(actor.Id,"RegionalContract","I fulfilled "+quest.Name+".",5,0,3);faction.Goodwill=Math.Min(100,faction.Goodwill+12);faction.Trust=Math.Min(100,faction.Trust+10);faction.Grievance=Math.Max(0,faction.Grievance-15);Chronicle("Quest","Completed "+quest.Name+"; the faction paid its actual reserve-backed reward.",faction.Id,site.Id,quest.ArtifactId,actor.Id);return new(true,"Contract complete; unique custody, reward and relations updated.");}
  return new(false,"Unknown regional action.");
 }
 private CommandResult BeginVisitorTrade(WorldCommand c,Definitions d)
 {var trader=Region.Traders.FirstOrDefault(t=>t.Id==c.TargetId&&t.State=="Visiting");if(trader==null||trader.Relief||!TradeAccess(trader.FactionId)||!Colony.People.TryGetValue(c.EntityId,out var p)||p.Drafted||!CanAct(c.EntityId)||c.Quantity is <1 or >20||c.DefinitionId=="brass"||trader.Cargo.GetValueOrDefault(c.DefinitionId)<c.Quantity)return new(false,"Select an available trader, goods and a capable undrafted worker.");var marker=Find(trader.MarkerId);var actor=Find(c.EntityId)!;if(marker==null||FindPath(actor,p,Index(marker.X,marker.Y,marker.Z),true,d)==null)return new(false,"Trader is unreachable.");var job=new ColonyJob{PawnId=actor.Id,Kind="RegionalTrade",TargetId=trader.Id,DefinitionId=c.DefinitionId,Cell=Index(marker.X,marker.Y,marker.Z),Work=c.Quantity,Claims=["trader:"+trader.Id]};if(!ReserveIngredients(job,new(){{"brass",TradePrice(c.DefinitionId,true)*c.Quantity}},d))return new(false,"Need reachable unclaimed brass.");Interrupt(actor.Id,d);return Start(job)?new(true,"Worker will carry payment to the visiting trader."):new(false,"Trader is reserved by another worker.");}
 private void AdvanceTraders(Definitions d)
 {
  foreach(var trader in Region.Traders)
  {if(trader.State=="Traveling"&&Tick>=trader.ArrivesAt){if(trader.Relief){int aidCell=NearestTerrainCell(Index(Width/2,Height/2),d);foreach(var item in trader.Cargo)Drop(item.Key,item.Value,aidCell,d);trader.Cargo.Clear();trader.State="Returned";Chronicle("Diplomacy","Treaty relief arrived from the ally's actual reserves.",trader.FactionId,Region.HomeSiteId);continue;}int cell=NearestTerrainCell(Index(Width/2+1,Height/2+5),d);var at=Position(cell);var result=Apply(new(CommandKind.Spawn,DefinitionId:"observatory-tablet",X:at.X,Y:at.Y,Z:at.Z),d);if(result.Accepted){trader.MarkerId=result.EntityId;Find(result.EntityId)!.Name="Visiting regional trader";trader.State="Visiting";Chronicle("Caravan","A reserve-funded trader arrived at the refuge.",trader.FactionId,Region.HomeSiteId);Danger.PauseSerial++;}}
   if(trader.State is "Traveling" or "Visiting"&&Tick>=trader.LeavesAt){foreach(var job in Autonomy.Jobs.Where(j=>j.Kind=="RegionalTrade"&&j.TargetId==trader.Id).ToArray())Interrupt(job.PawnId,d);var f=Region.Factions.First(f=>f.Id==trader.FactionId);foreach(var cargo in trader.Cargo)f.Reserves[cargo.Key]=Math.Min(10000,f.Reserves.GetValueOrDefault(cargo.Key)+cargo.Value);trader.Cargo.Clear();if(Find(trader.MarkerId)!=null)Apply(new(CommandKind.Remove,trader.MarkerId),d);trader.MarkerId=0;trader.State="Returned";Chronicle("Caravan","The trader returned unsold stock and receipts to its faction.",f.Id);}}
 }
}
